package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	mod := int64(1000000007)
	limit := 2*n + 1

	notPrime := make([]bool, limit+2)
	notPrime[0], notPrime[1] = true, true
	primes := make([]int, 0)

	for i := 0; i <= limit; i++ {
		if notPrime[i] {
			continue
		}
		primes = append(primes, i)
		for j := i * i; j <= limit; j += i {
			notPrime[j] = true
		}
	}

	chooseMod := func(m, n int, mod int64) int64 {
		if n > m-n {
			n = m - n
		}
		factors := make([]int, len(primes))
		for pos, x := range primes {
			if x > m {
				break
			}
			for i := x; i <= m; i += x {
				if i > n && i <= m-n {
					continue
				}
				y := i
				c := 0
				for y%x == 0 {
					y /= x
					c++
				}
				if i <= n {
					factors[pos] -= c
				} else {
					factors[pos] += c
				}
			}
		}
		result := int64(1)
		for pos, x := range factors {
			y := int64(primes[pos])
			for i := 0; i < x; i++ {
				result = (result * y) % mod
			}
		}
		return result
	}

	ans := (2*chooseMod(2*n+1, n, mod) - 1) % mod
	if ans < 0 {
		ans += mod
	}
	fmt.Println(ans)
}

